'use client';
import Link from 'next/link';import {useState,useEffect} from 'react';import {useQuery,useQueryClient} from '@tanstack/react-query';
import {useConnection,useConnect,useDisconnect,useWalletClient,useSwitchChain} from 'wagmi';
import {parseUnits,formatEther,keccak256,decodeEventLog,type Address,type Abi,type Hex,type WalletClient} from 'viem';
import {Shield,ArrowUpRight,ArrowRight,Wallet,Layers,FileCheck2,Activity,Compass,ExternalLink,Check,LockKeyhole,RefreshCw,AlertCircle,Download,Menu,X} from 'lucide-react';
import {Button} from './ui/button';
import {WeatherEvidencePanel} from './weather-evidence';
