type View='home'|'market'|'explore'|'buy'|'underwrite'|'policies'|'resolution'|'operator';
const navigation=[['explore','Explore','/explore/',Compass],['buy','Protection','/buy/',Shield],['underwrite','Underwrite','/underwrite/',Layers],['policies','Portfolio','/policies/',FileCheck2],['resolution','Resolution','/resolution/',Activity]] as const;
const titles={home:'Underwrite uncertainty.',market:'Market terms',explore:'Explore risk markets',buy:'A clearer kind of protection.',underwrite:'Put capital behind conviction.',policies:'Your exposure, in perspective.',resolution:'The evidence behind every outcome.',operator:'A transparent demonstration.'};
const subtitles={home:'An onchain marketplace for real-world risk.',market:'Inspect the exact event and available offers.',explore:'Defined events. Transparent terms. Fully reserved claims.',buy:'Review the exact trigger. Compare funded quotes. Choose your cover.',underwrite:'Inspect capital, reserved exposure, realized premiums, and claims.',policies:'Protection, underwriting positions, and your onchain history in one place.',resolution:'Inspect the source, snapshot, authority, and transaction behind settlement.',operator:'Authorized wallet actions. Deterministic fixtures. Real contract transitions.'};

type Prepared={spec:Record<string,unknown>;terms:Record<string,unknown>;bundle?:{manifest:Record<string,unknown>;manifestHash:Hex;responseHash:Hex;raw:string}};
function Stat({label,value,detail}:{label:string;value:string;detail?:string}){return <div className="stat"><span className="eyebrow">{label}</span><strong>{value}</strong>{detail&&<small>{detail}</small>}</div>;}
function HashLink({hash,d}:{hash:string;d:Deployment}){return d.chainId===31337?<code title={hash}>{short(hash)} · local chain</code>:<a className="hash-link" href={`${d.explorer}/tx/${hash}`} target="_blank" rel="noreferrer">{short(hash)} <ExternalLink size={12}/></a>;}
function Field({label,children}:{label:string;children:React.ReactNode}){return <div className="field"><span>{label}</span><strong>{children}</strong></div>;}
export function Dashboard({view}:{view:View}){
  const [confirmedPolicy,setConfirmedPolicy]=useState<string>();
  const [showActivity,setShowActivity]=useState(false);
  const [override,setOverride]=useState<Deployment|null>(null);const [notice,setNotice]=useState('');const [txHash,setTxHash]=useState<Hex>();const [pending,setPending]=useState(false);const [mobileMenu,setMobileMenu]=useState(false);
  const connection=useConnection(),{connect,connectors,error:connectError}=useConnect(),{disconnect}=useDisconnect(),{data:walletClient}=useWalletClient(),{switchChain}=useSwitchChain();const cache=useQueryClient();
  const deployment=useQuery({queryKey:['deployment'],queryFn:async()=>{const r=await fetch('/deployment.json',{cache:'no-store'});if(!r.ok)throw new Error('Deployment configuration unavailable');return await r.json() as Deployment;}});
  const d=override||deployment.data;const protocol=useQuery({queryKey:['protocol',d?.contracts?.manager,d?.chainId,connection.address],queryFn:()=>readProtocol(d!,connection.address),enabled:!!d?.contracts,refetchInterval:15000});
  const history=useQuery({queryKey:['history',d?.contracts?.manager,d?.chainId],queryFn:()=>readHistory(d!),enabled:showActivity&&!!d?.contracts&&protocol.isSuccess&&['underwrite','policies','resolution','operator'].includes(view),refetchInterval:60000,staleTime:30000});
  const data=protocol.data;const wrongNetwork=connection.isConnected&&!!d&&connection.chainId!==d.chainId;
  const ready=!!d?.contracts&&!!data&&!protocol.isError&&connection.isConnected&&!wrongNetwork&&!pending;
  useEffect(()=>{const raw=sessionStorage.getItem('aegis-deployment');if(raw){try{setOverride(JSON.parse(raw));}catch{sessionStorage.removeItem('aegis-deployment');}}},[]);
  async function refresh(){await cache.invalidateQueries({queryKey:['protocol']});await cache.invalidateQueries({queryKey:['history']});}
  async function transact(to:Address,abi:Abi,functionName:string,args:readonly unknown[]=[]) {
    if(!d?.contracts||!walletClient||!connection.address) {setNotice('Connect a wallet to a verified deployment first.');return;}
    if(wrongNetwork){setNotice(`Switch your wallet to chain ${d.chainId}.`);return;}
    setPending(true);setConfirmedPolicy(undefined);setTxHash(undefined);setNotice('Reviewing transaction and estimating gas…');
    let submittedHash:Hex|undefined;let executed=false;
    try {
      const client=publicClient(d),params={account:connection.address,address:to,abi,functionName,args};const simulation=await client.simulateContract(params);const estimated=await client.estimateContractGas(params);const gas=estimated+estimated/10n;const fees=await client.estimateFeesPerGas();const balance=await client.getBalance({address:connection.address});
      if(balance<gas*fees.maxFeePerGas)throw new Error(`Insufficient test MON for the estimated fee (${formatEther(gas*fees.maxFeePerGas)} MON). Use the testnet faucet.`);
      setNotice(`Approve in your wallet. Maximum estimated gas fee: ${formatEther(gas*fees.maxFeePerGas)} MON. Monad charges the gas limit.`);
      const hash=await walletClient.writeContract({...simulation.request,gas,chain:walletClient.chain});submittedHash=hash;setTxHash(hash);setNotice('Transaction submitted. Waiting for successful execution…');
      const receipt=await client.waitForTransactionReceipt({hash});if(receipt.status!=='success')throw new Error('Transaction reverted. No success state has been recorded.');executed=true;
      if(d.chainId===10143){for(let attempt=0;attempt<20;++attempt){const finalized=await client.getBlock({blockTag:'finalized'});if(finalized.number>=receipt.blockNumber)break;if(attempt===19)throw new Error('Executed transaction is awaiting finality. Inspect its explorer link before retrying.');await new Promise(resolve=>setTimeout(resolve,500));}}
      for(const log of receipt.logs){try{const decoded=decodeEventLog({abi:abis.AegisPolicyManager,data:log.data,topics:log.topics});if(decoded.eventName==='PolicyPurchased')setConfirmedPolicy(decoded.args.policyId.toString());}catch{}}
      setNotice('Transaction confirmed. Refreshing onchain balances…');await refresh();
      const state=cache.getQueryState(['protocol',d.contracts.manager,d.chainId,connection.address]);
      setNotice(state?.status==='error'?'Transaction confirmed. Balance refresh is delayed by RPC availability. Do not repeat the transaction.':'Transaction confirmed. Onchain balances and status refreshed.');
    }catch(error){setNotice(executed?'Transaction executed successfully. Finality or balance refresh is delayed; inspect its explorer link before retrying.':isRateLimitError(error)?submittedHash?'Transaction submitted. The RPC is busy; check its explorer link before retrying.':'The RPC is busy. No transaction was submitted; wait for reads to recover and retry.':error instanceof Error?error.message:'Transaction failed. Inspect the wallet and RPC response.');}finally{setPending(false);}
  }
  async function installDeployment(candidate:Deployment){
    if(![10143,31337].includes(candidate.chainId)||!candidate.contracts||candidate.deploymentBlock===null)throw new Error('Import a deployment with actual contract addresses and a deployment block.');
    const client=publicClient(candidate);if(await client.getChainId()!==candidate.chainId)throw new Error('Deployment RPC chain mismatch');
    for(const address of Object.values(candidate.contracts))if(!await client.getCode({address}))throw new Error('A configured address has no deployed code');
    const token=await client.readContract({address:candidate.contracts.manager,abi:abis.AegisPolicyManager,functionName:'asset'}),resolver=await client.readContract({address:candidate.contracts.manager,abi:abis.AegisPolicyManager,functionName:'adapter'});
    if(token.toLowerCase()!==candidate.contracts.token.toLowerCase()||resolver.toLowerCase()!==candidate.contracts.resolver.toLowerCase())throw new Error('Contract binding mismatch');
    sessionStorage.setItem('aegis-deployment',JSON.stringify(candidate));setOverride(candidate);setNotice('Deployment addresses and contract bindings verified against RPC.');
  }
  const loading=deployment.isPending||protocol.isLoading;
  return <div className="app-shell">
    <header className="site-header"><div className="topbar"><Link href="/" className="brand" aria-label="Aegis home"><svg className="brand-symbol" viewBox="0 0 32 34" aria-hidden="true"><path d="M16 2 30 28H21L16 18 11 28H2Z" fill="currentColor"/><path d="m12 12 4-8 4 8Z" fill="#836EF9"/><path d="M2 32h28" stroke="currentColor" strokeWidth="2"/></svg>AEGIS</Link><nav className={`primary-nav ${mobileMenu?'nav-open':''}`} aria-label="Main navigation">{navigation.map(([key,label,href])=><Link aria-current={view===key?'page':undefined} onClick={()=>setMobileMenu(false)} href={href} key={key} className={view===key||view==='market'&&key==='explore'?'selected':''}>{label}</Link>)}</nav><div className="topbar-actions"><Link className="network-badge" href="/operator/" title={protocol.error?'RPC unavailable':data?'Contract reads connected':'Connecting to configured RPC'}><span className={protocol.error?'connection-error':data?'connection-ready':'connection-pending'}/>{d?.chainId===31337?'Local EVM':'Monad Testnet'}</Link>{connection.isConnected?<Button variant="outline" onClick={()=>disconnect()}><Wallet size={15}/>{short(connection.address!)}<span className="disconnect">Disconnect</span></Button>:<Button onClick={()=>connectors[0]?connect({connector:connectors[0]}):setNotice('Open this app in a browser with MetaMask or Rabby installed.')}><Wallet size={16}/>Connect wallet</Button>}<button className="mobile-toggle" aria-label="Toggle navigation" aria-expanded={mobileMenu} onClick={()=>setMobileMenu(!mobileMenu)}>{mobileMenu?<X/>:<Menu/>}</button></div></div></header>
    <main className="main" id="main-content"><div className="content"><div className="workspace-bar"><span>Risk marketplace <span className="workspace-separator">/</span> {view==='home'?'Overview':titles[view]}</span><div><Link href="/#how-it-works">How it works</Link><Link href="/docs/">Documentation</Link><Link href="/operator/">Demo operator</Link>{d?.contracts&&<Button variant="ghost" aria-label="Refresh onchain data" onClick={()=>void refresh()}><RefreshCw size={15}/></Button>}</div></div>
    {!['home','explore','market'].includes(view)&&<div className="page-heading"><div><h1>{titles[view]}</h1><p>{subtitles[view]}</p></div></div>}
    {wrongNetwork&&<div className="alert"><AlertCircle size={18}/>Your wallet is on a different network.<Button variant="outline" onClick={()=>switchChain({chainId:d!.chainId},{onError:error=>setNotice(error.message)})}>Switch network</Button></div>}
    {(notice||connectError)&&<div className="transaction-notice" role="status"><Activity size={18}/><span>{notice||connectError?.message}</span>{txHash&&d&&<HashLink hash={txHash} d={d}/>}</div>}
    {protocol.error&&<div className="alert">{isRateLimitError(protocol.error)?'Balance refresh delayed: the public RPC is busy. Reads retry with backoff.':'Contract connection unavailable.'} {data?`Showing the last successful read at ${date(data.now)}. Financial actions are paused.`:'Market and financial data cannot be read.'} Confirmed transactions do not need to be repeated. Use refresh to retry reads.</div>}
    {d&&!d.contracts&&<div className="deployment-banner"><LockKeyhole size={17}/><div><strong>Deployment awaits wallet signing.</strong> Contract addresses are not configured. Financial actions become available after verified deployment; terms below are reference information.</div><Link href="/operator/">Deployment setup <ArrowUpRight size={14}/></Link></div>}
    {confirmedPolicy&&<div className="confirmation-card"><Check size={18}/><div><strong>Policy #{confirmedPolicy} issued.</strong><p>Your protection is confirmed onchain. Inspect coverage and premium in your portfolio.</p></div><Link href="/policies/">View policy <ArrowUpRight size={15}/></Link></div>}
    {view==='home'&&<Home data={data||undefined} loading={loading}/>}
    {view==='explore'&&<MarketDiscovery data={data||undefined} loading={loading}/>}
    {view==='market'&&<MarketDetail data={data||undefined}>{id=><BuyPanel d={d} data={data||undefined} ready={ready} pending={pending} transact={transact} eventId={id}/>}</MarketDetail>}
    {view==='buy'&&<BuyPanel d={d} data={data||undefined} ready={ready} pending={pending} transact={transact}/>}
    {view==='underwrite'&&<VaultPanel d={d} data={data||undefined} address={connection.address} ready={ready} transact={transact}/>}
    {view==='policies'&&<PortfolioPanel data={data||undefined} address={connection.address} history={history.data||[]} renderPolicies={policies=>policies.map(p=>{const event=data!.events.find(e=>e.id===p.eventId);return <section className="panel policy-card" key={p.id.toString()}><div className="card-top"><h3>Policy #{p.id.toString()} · Pune rainfall</h3><span className="pill">{p.settled?`Settled ${['','YES','NO','INVALID'][p.outcome]}`:statusNames[event?.resolution.status||1]}</span></div><div className="fields-grid"><Field label="Coverage">{money(p.coverage)} mUSDC</Field><Field label="Premium">{money(p.premium)} mUSDC</Field><Field label="Claim paid">{money(p.payout)} mUSDC</Field><Field label="Quoting vault">#{p.vaultId.toString()}</Field><Field label="Observation">{event?date(event.terms.observationStart):'—'}</Field><Field label="Terms commitment"><code title={p.termsHash}>{short(p.termsHash)}</code></Field></div>{event?.terms.mode===1&&<div className="simulation-label">TESTNET DEMONSTRATION — SIMULATED EVENT RESULT</div>}{!p.settled&&<Button disabled={!ready||(event?.resolution.status||0)<3} onClick={()=>void transact(d!.contracts!.manager,abis.AegisPolicyManager,'settlePolicy',[p.id])}>Settle policy <ArrowRight size={15}/></Button>}</section>;})} renderHash={hash=><HashLink hash={hash} d={d!}/>}/>}
    {view==='resolution'&&<>{d&&<HistoricalDiscovery deployment={d}/>}<div className="trust-card"><Shield size={22}/><div><strong>Trusted resolver, inspectable evidence.</strong><p>AEGIS v1 has a designated authority and no challenge window. Evidence hashes detect changed bytes; they do not independently prove weather truth.</p></div><span className="pill">{data?short(data.authority):'AUTHORITY PENDING'}</span></div>{data?.events.map(e=><EventPanel key={e.id.toString()} event={e} d={d!} ready={ready} transact={transact} authority={data.authority} activity={(history.data||[]).filter(log=>log.requestId===e.requestId||log.eventId===e.id||(log.policyId!==undefined&&data.policies.some(policy=>policy.id===log.policyId&&policy.eventId===e.id)))}/>)}{!data?.events.length&&<Empty title="No registered event yet." text="A registered event fixes the dataset, snapshot rules, deadline, and resolver before a buyer purchases."/>}</>}
    {view==='operator'&&d&&<Operator d={d} data={data||undefined} ready={ready} address={connection.address} walletClient={walletClient} transact={transact} installDeployment={installDeployment} setNotice={setNotice}/>}
    {!['home','explore','market','policies'].includes(view)&&<details className="panel" onToggle={e=>setShowActivity(e.currentTarget.open)}><summary>Advanced · onchain activity</summary><section className="panel history-panel"><div className="card-top"><h3>Onchain activity</h3><span className="eyebrow">ACTUAL CONTRACT EVENTS</span></div>{history.data?.slice(0,15).map((log,i)=><div className="history-row" key={`${log.hash}-${i}`}><span><Activity size={14}/>{log.event}</span><small>Block {log.block?.toString()}</small><HashLink hash={log.hash!} d={d!}/></div>)}{!history.data?.length&&<p className="muted">{history.isFetching?'Loading confirmed activity from the deployment block…':history.error?'Activity is temporarily unavailable. Confirmed transactions do not need to be repeated.':'No confirmed contract activity found.'}</p>}{history.error&&<details className="error"><summary>Activity retrieval details</summary><p>{history.error.message}</p></details>}</section></details>}
    <footer className="disclosure"><Shield size={18}/><div><strong>{d?.chainId===31337?'Local demonstration. Mock funds have no monetary value.':'Educational testnet software. Mock funds have no monetary value.'}</strong><p>No real-world coverage. No guaranteed returns. Not licensed or independently audited. Parametric payouts may differ from actual losses; gridded rainfall may differ from conditions at your venue.</p></div><a href="https://aegis-evidence.sweetmoss1.chatgpt.site" target="_blank" rel="noreferrer">Evidence archive <ExternalLink size={13}/></a></footer>
    </div></main><div className="footer-brand"><span>AEGIS</span><p>Explore risk. Buy protection. Underwrite outcomes.</p><small>Built on Monad · {d?.chainId===31337?'Local demonstration':'Educational testnet prototype'}</small></div></div>;
}
type Tx=(to:Address,abi:Abi,name:string,args?:readonly unknown[])=>Promise<void>;
function Empty({title,text}:{title:string;text:string}){return <div className="empty"><Shield size={30}/><h3>{title}</h3><p>{text}</p></div>;}
function BuyPanel({d,data,ready,pending,transact,eventId}:{d?:Deployment;data?:Protocol;ready:boolean;pending:boolean;transact:Tx;eventId?:bigint}){
  const quotes=data?.quotes.filter(q=>q.status===1&&q.expiry>data.now&&(!eventId||q.eventId===eventId))||[];
  const selectedEvent=data?.events.find(e=>e.id===eventId);
  const specification=useQuery({queryKey:['weather-spec',d?.chainId,selectedEvent?.terms.specHash],queryFn:()=>loadWeatherSpecification(selectedEvent!,d!),enabled:!!selectedEvent&&!!d,retry:0});
  return <><div className={eventId?'protection-layout':''}><div className="protection-context"><div className="product-spec panel"><div className="card-top"><h2>{specification.data?.city==='mumbai'?'Mumbai':selectedEvent?.weather?.displayName||'Weather'} rainfall cover</h2><span className="pill">PARAMETRIC · FIXED PAYOUT</span></div><div className="fields-grid"><Field label="Governing source">Open-Meteo · ERA5 daily rain sum</Field><Field label="Trigger">{eventId?`${millimetres(data!.events.find(e=>e.id===eventId)!.terms.thresholdMilliMm)} mm or more`:"Defined in each dated specification"}</Field><Field label="Requested location">{specification.data?`${specification.data.source.parameters.latitude}° N, ${specification.data.source.parameters.longitude}° E`:"Defined by the committed market specification"}</Field><Field label="Governing grid cell">{specification.data?`${specification.data.source.governingGrid.latitude}° N, ${specification.data.source.governingGrid.longitude}° E`:"Defined by the committed market specification"}</Field><Field label="Time convention">00:00–00:00 · Asia/Kolkata</Field><Field label="Advance purchase">{selectedEvent?`${selectedEvent.terms.minimumLeadTime/3600n} hours before observation`:'Defined by each event'}</Field></div><p className="muted">A frozen served reanalysis snapshot governs settlement, including preliminary ERA5T. Later revisions do not change a committed outcome. Each quote below links its exact dated specification.</p></div>{selectedEvent&&<><section className="panel"><h3>Event specification</h3><div className="fields-grid"><Field label="Observation starts">{date(selectedEvent.terms.observationStart)}</Field><Field label="Observation ends">{date(selectedEvent.terms.observationEnd)}</Field><Field label="Purchase cutoff">{date(selectedEvent.terms.purchaseCutoff)}</Field><Field label="Capture eligible">{date(selectedEvent.terms.captureEligibleAt)}</Field><Field label="Resolution deadline">{date(selectedEvent.terms.resolutionDeadline)}</Field><Field label="Specification hash"><code>{short(selectedEvent.terms.specHash)}</code></Field></div><a className="text-link" href={selectedEvent.terms.specificationURI} target="_blank" rel="noreferrer">Inspect committed specification <ExternalLink size={13}/></a></section><ForecastReference event={selectedEvent} deployment={d!}/></>}</div><div className="protection-offers"><div className="section-heading"><h2>Compare underwriting offers</h2><span className="eyebrow">MANAGER-SET PRICES</span></div><div className="quote-grid">{quotes.map(q=>{const event=data!.events.find(e=>e.id===q.eventId),vault=data!.vaults.find(v=>v.id===q.vaultId);const capacity=!!vault&&vault.availableCapacity>=q.coverage&&vault.phase===1&&data!.now<vault.issuanceDeadline&&event?.resolution.status===1&&data!.now<event.terms.purchaseCutoff&&event.exposure+q.coverage<=event.terms.maxEventCoverage&&((event.buyerPurchased||0n)+q.coverage<=event.terms.maxBuyerCoverage);const approved=(data!.allowance||0n)>=q.premium;const enough=(data!.tokenBalance||0n)>=q.premium;return <section className="panel quote-card" key={q.id.toString()}><div className="card-top"><span className="pill">Quote #{q.id.toString()} · Vault #{q.vaultId.toString()}</span><span className={capacity?'positive':'error'}>{capacity?'Full collateral available':'Purchase unavailable'}</span></div><h3>{money(q.coverage)} <small>mUSDC coverage</small></h3><div className="premium-price">{money(q.premium)} <span>mUSDC premium</span></div><Field label="Premium / coverage">{premiumRatio(q.premium,q.coverage)} · price ratio</Field><Field label="Wallet balance">{money(data!.tokenBalance)} mUSDC</Field><Field label="Quoting manager">{vault?short(vault.quotingManager):'—'}</Field><Field label="Observation starts">{event?date(event.terms.observationStart):'—'}</Field><Field label="Observation ends">{event?date(event.terms.observationEnd):'—'}</Field><Field label="Purchase cutoff">{event?date(event.terms.purchaseCutoff):'—'}</Field><Field label="Quote expires">{date(q.expiry)}</Field><Field label="Available vault capital">{money(vault?.availableCapacity)} mUSDC</Field>{event&&<a className="text-link" href={event.terms.specificationURI} target="_blank" rel="noreferrer">Exact specification <ExternalLink size={13}/></a>}{event?.terms.mode===1&&<div className="simulation-label">TESTNET DEMONSTRATION — SIMULATED EVENT RESULT</div>}<div className="coverage-outcomes"><div><Check size={14}/><span>If the trigger occurs</span><strong>{money(q.coverage)} mUSDC payout</strong></div><div><X size={14}/><span>If the trigger does not occur</span><strong>0 mUSDC payout</strong></div><p>Premium is paid in either outcome. Formal INVALID settlement refunds the premium. This ratio is a price, not an event probability.</p></div><p className="tiny">Pricing reference unavailable. Premium is an unvalidated underwriting offer. Claims are reserved atomically at purchase.</p><Button disabled={!ready||!capacity||!enough||pending} onClick={()=>void transact(approved?d!.contracts!.manager:d!.contracts!.token,approved?abis.AegisPolicyManager:abis.MockUSDC,approved?'purchase':'approve',approved?[q.id]:[d!.contracts!.manager,q.premium])}>{approved?'Buy this coverage':'Approve premium'} <ArrowRight size={15}/></Button>{ready&&!enough&&<p className="error">Insufficient mock USDC. Claim test tokens below.</p>}</section>;})}</div>{!quotes.length&&<Empty title="No purchasable quote is available." text="The manager must publish an unexpired quote from a funded underwriting vault. Expired or consumed quotes cannot be purchased."/>}</div></div><section className="basis-risk panel"><Shield size={20}/><div><h3>Understand your coverage</h3><p>Parametric protection pays against the committed trigger. Your actual loss may differ, and gridded rainfall may differ from conditions at your venue. Only the exact event specification governs settlement.</p></div></section><div className="token-tools panel"><div><h3>Test funds for the demonstration</h3><p>Claim 10,000 valueless mock USDC once per wallet per day. Test MON is also required for gas.</p></div><Button variant="outline" disabled={!ready} onClick={()=>void transact(d!.contracts!.token,abis.MockUSDC,'faucet')}>Claim mock USDC</Button><a href="https://faucet.monad.xyz" target="_blank" rel="noreferrer" className="text-link">MON faucet <ExternalLink size={14}/></a></div></>;
}
function VaultPanel({d,data,address,ready,transact}:{d?:Deployment;data?:Protocol;address?:Address;ready:boolean;transact:Tx}){
  const [amount,setAmount]=useState('1000'),[premium,setPremium]=useState('25'),[eventId,setEventId]=useState('1');
  const validAmount=(value:string)=>/^\d+(\.\d{1,6})?$/.test(value)&&parseUnits(value,6)>0n;
  const depositValid=validAmount(amount),premiumValid=validAmount(premium);
  const sum=(field:'accountedAssets'|'reservedCoverage'|'availableCapacity'|'realizedPremiums'|'settledPayouts')=>data?.vaults.reduce((a,v)=>a+v[field],0n);
  return <><div className="stats-row vault-overview"><Stat label="Total vault assets" value={money(sum('accountedAssets'))} detail="mUSDC · excludes surplus"/><Stat label="Reserved exposure" value={money(sum('reservedCoverage'))} detail="mUSDC · maximum claims"/><Stat label="Available capacity" value={money(sum('availableCapacity'))} detail="mUSDC · unreserved capital"/><Stat label="Realized premiums" value={money(sum('realizedPremiums'))} detail="mUSDC · settled policies"/><Stat label="Claims paid" value={money(sum('settledPayouts'))} detail="mUSDC · settled payouts"/><Stat label="Net underwriting result" value={money(data?sum('realizedPremiums')!-sum('settledPayouts')!:undefined)} detail="mUSDC · premiums less claims"/></div>{data?.vaults.map(v=>{const owned=address?.toLowerCase()===v.quotingManager.toLowerCase();const denominator=v.accountedAssets||1n;const width=Number(v.reservedCoverage*10000n/denominator)/100;return <section className="panel vault-panel" key={v.id.toString()}><div className="card-top"><div><span className="eyebrow">{v.mode===1?'SYNTHETIC DEMO EPOCH':'LIVE-DATA EPOCH'}</span><h2>Underwriting vault #{v.id.toString()}</h2></div><span className="pill">{phaseNames[v.phase]}</span></div><div className="stats-row compact"><Stat label="Accounted assets" value={money(v.accountedAssets)}/><Stat label="Reserved claims" value={money(v.reservedCoverage)}/><Stat label="Available capacity" value={money(v.availableCapacity)}/><Stat label="Your shares" value={money(v.shares)}/></div><div className="capital-bar"><div style={{width:`${width}%`}}/></div><div className="bar-legend"><span><i className="reserved-swatch"/>Reserved maximum risk</span><span><i/>Unreserved capital</span></div><div className="fields-grid"><Field label="Deposited capital">{money(v.totalDeposited)} mUSDC</Field><Field label="Earned premiums">{money(v.realizedPremiums)} mUSDC</Field><Field label="Claims paid">{money(v.settledPayouts)} mUSDC</Field><Field label="Realized underwriting result">{money(v.realizedPremiums-v.settledPayouts)} mUSDC</Field><Field label="Unexpected deposits (excluded)">{money(v.unassignedSurplus)} mUSDC</Field><Field label="Active policies">{v.activePolicies.toString()}</Field></div><div className="vault-actions"><label>Deposit amount<input aria-label={`Deposit amount vault ${v.id}`} value={amount} onChange={e=>setAmount(e.target.value)} inputMode="decimal"/></label><Button variant="outline" disabled={!ready||v.phase!==0||!depositValid||!v.invited} onClick={()=>void transact(d!.contracts!.token,abis.MockUSDC,'approve',[v.address,parseUnits(amount,6)])}>Approve deposit</Button><Button disabled={!ready||v.phase!==0||!depositValid||!v.invited||parseUnits(amount,6)>(data!.tokenBalance||0n)||parseUnits(amount,6)>(v.depositAllowance||0n)} onClick={()=>void transact(v.address,abis.AegisUnderwritingVault,'deposit',[parseUnits(amount,6)])}>Deposit mUSDC</Button>{owned&&<Button variant="outline" disabled={!ready||v.phase!==0} onClick={()=>void transact(v.address,abis.AegisUnderwritingVault,'beginUnderwriting')}>Open underwriting</Button>}</div>{owned&&v.phase===1&&<div className="vault-actions"><label>Event<select value={eventId} onChange={e=>setEventId(e.target.value)}>{data!.events.filter(e=>e.terms.mode===v.mode).map(e=><option key={e.id.toString()} value={e.id.toString()}>Event #{e.id.toString()}</option>)}</select></label><label>Premium (mUSDC)<input value={premium} onChange={e=>setPremium(e.target.value)} inputMode="decimal"/></label><div className="quote-economics"><span>Fixed coverage: 200 mUSDC</span><span>If YES: {premiumValid?money(parseUnits(premium,6)-200_000_000n):"—"} mUSDC net</span><span>If NO: +{premiumValid?money(parseUnits(premium,6)):"—"} mUSDC net</span></div><Button disabled={!ready||!premiumValid||v.availableCapacity<200_000_000n||!data!.events.some(e=>e.id.toString()===eventId&&e.terms.mode===v.mode&&e.terms.purchaseCutoff>data!.now&&e.resolution.status===1)} onClick={()=>{const event=data!.events.find(e=>e.id===BigInt(eventId));if(event)void transact(d!.contracts!.manager,abis.AegisPolicyManager,'publishQuote',[event.id,v.id,200_000_000n,parseUnits(premium,6),[event.terms.purchaseCutoff,data!.now+86400n,v.issuanceDeadline].reduce((a,b)=>a<b?a:b)]);}}>Publish 200-mUSDC quote</Button></div>}<div className="vault-actions">{owned&&v.phase<2&&<Button variant="outline" disabled={!ready} onClick={()=>void transact(v.address,abis.AegisUnderwritingVault,'endIssuance')}>End issuance</Button>}{v.phase===2&&<Button variant="outline" disabled={!ready||v.activePolicies>0n} onClick={()=>void transact(v.address,abis.AegisUnderwritingVault,'closeEpoch')}>Close settled epoch</Button>}<Button disabled={!ready||v.phase!==3||!v.shares} onClick={()=>void transact(v.address,abis.AegisUnderwritingVault,'redeem',[v.shares!])}>Redeem all shares</Button><span className="lock-note">{address&&!v.invited?"Wallet is not invited to deposit. ":""}<LockKeyhole size={14}/>{v.phase===3?'Redemption eligible':'Redemption locked until epoch closure'}</span></div><VaultExposureTable data={data!} vaultId={v.id}/><p className="tiny">Share transfers are disabled. No APY or guaranteed return. Wallet must be invited to deposit.</p></section>;})}{!data?.vaults.length&&<Empty title="Vaults appear after deployment and funding." text="One funded vault establishes the core flow. A separately managed competing vault supplies a second offer afterward."/>}</>;
}
function EventPanel({event:e,d,ready,transact,authority,activity}:{authority:Address;activity:Awaited<ReturnType<typeof readHistory>>;event:Protocol['events'][number];d:Deployment;ready:boolean;transact:Tx}){
  const [verification,setVerification]=useState('');const history=useQuery({queryKey:['evidence-history',d.evidenceOrigin,e.id.toString()],queryFn:async()=>{const response=await fetch(`${d.evidenceOrigin}/events?manager=${d.contracts!.manager}&eventId=${e.id}`);if(!response.ok)throw new Error('Evidence history unavailable');return response.json() as Promise<{attempts:{id:number;status:string;manifest_hash:Hex;completed_at:number}[]}>;},retry:0});
  async function verify(){try{const response=await fetch(e.resolution.evidenceURI);if(!response.ok)throw new Error('Evidence object unavailable');const bytes=new Uint8Array(await response.arrayBuffer());if(keccak256(bytes)!==e.resolution.manifestHash)throw new Error('Manifest/timeout bytes do not match onchain hash');if(e.resolution.status===5&&e.terms.mode===0){setVerification('Timeout commitment bytes match the onchain digest. Deadline and Open-state guard are enforced by the resolver.');return;}const manifest=JSON.parse(new TextDecoder().decode(bytes));const raw=await fetch(`${new URL(e.resolution.evidenceURI).origin}/evidence/${manifest.responseHash}`);if(!raw.ok)throw new Error('Raw response unavailable');const rawBytes=new Uint8Array(await raw.arrayBuffer());const specification=await fetch(e.terms.specificationURI);if(!specification.ok)throw new Error('Specification unavailable');const spec=await specification.json();verifySpecificationTerms(spec,e.terms);const checked=verifyBundle(manifest,rawBytes,spec);if(checked.manifestHash!==e.resolution.manifestHash||checked.responseHash!==e.resolution.responseHash)throw new Error('Archived evidence differs from onchain commitments');if(manifest.specHash!==e.terms.specHash||manifest.sourceConfigHash!==e.terms.sourceConfigHash||String(manifest.eventId)!==e.id.toString()||manifest.adapter.toLowerCase()!==d.contracts!.resolver.toLowerCase()||String(manifest.validation?.rainfallMilliMm)!==e.resolution.rainfallMilliMm.toString())throw new Error('Evidence binding or calculation mismatch');setVerification('Manifest bytes, raw response bytes, event binding, and committed rainfall match. Source authenticity remains trusted.');}catch(error){setVerification(error instanceof Error?error.message:'Evidence verification failed');}}
  return <section className="panel event-panel"><div className="card-top"><h2>Event #{e.id.toString()} · Pune rainfall</h2><span className="pill">{statusNames[e.resolution.status]}</span></div>{e.terms.mode===1&&<div className="simulation-label">TESTNET DEMONSTRATION — SIMULATED EVENT RESULT</div>}<ResolutionTimeline event={e}/><WeatherEvidencePanel event={e} deployment={d}/><div className="fields-grid"><Field label="Observation starts">{date(e.terms.observationStart)}</Field><Field label="Observation ends">{date(e.terms.observationEnd)}</Field><Field label="Capture eligible">{date(e.terms.captureEligibleAt)}</Field><Field label="Resolution deadline">{date(e.terms.resolutionDeadline)}</Field><Field label="Threshold">{millimetres(e.terms.thresholdMilliMm)} mm · inclusive</Field><Field label="Onchain rainfall">{e.resolution.status>=2&&e.resolution.status!==5?`${millimetres(e.resolution.rainfallMilliMm)} mm`:'No valid commitment'}</Field><Field label="Resolver authority"><code>{authority}</code></Field><Field label="Evidence manifest hash"><code>{BigInt(e.resolution.manifestHash)!==0n?e.resolution.manifestHash:"Not committed"}</code></Field><Field label="Raw response hash"><code>{BigInt(e.resolution.responseHash)!==0n?e.resolution.responseHash:"Not committed"}</code></Field><Field label="Trigger comparison">{e.resolution.status>=2&&e.resolution.status!==5?`${e.resolution.rainfallMilliMm} ${e.resolution.rainfallMilliMm>=e.terms.thresholdMilliMm?"≥":"<"} ${e.terms.thresholdMilliMm} milli-mm`:"Awaiting valid evidence"}</Field><Field label="Snapshot time">{e.resolution.capturedAt?date(e.resolution.capturedAt):'—'}</Field><Field label="Specification hash"><code title={e.terms.specHash}>{short(e.terms.specHash)}</code></Field></div><p className="muted">Source: archive-api.open-meteo.com/v1/archive · models=era5 · daily=rain_sum · mm · Asia/Kolkata · nearest cell. Requested coordinates and the exact dated request are read from each immutable specification above. First valid archived snapshot from day 5 to before day 14. Preliminary ERA5T is accepted; later corrections do not replace the snapshot.</p><div className="evidence-actions"><a className="text-link" href={e.terms.specificationURI} target="_blank" rel="noreferrer">Download specification <Download size={14}/></a>{e.resolution.evidenceURI&&<><a className="text-link" href={e.resolution.evidenceURI} target="_blank" rel="noreferrer">Evidence / timeout commitment <Download size={14}/></a>{BigInt(e.resolution.responseHash)!==0n&&<a className="text-link" href={`${d.evidenceOrigin}/evidence/${e.resolution.responseHash}`} target="_blank" rel="noreferrer">Download raw response <Download size={14}/></a>}<Button variant="outline" onClick={()=>void verify()}>Verify evidence hashes</Button></>}{e.resolution.status===2&&<Button disabled={!ready} onClick={()=>void transact(d.contracts!.resolver,abis.DemoWeatherResolver,'finalize',[e.requestId])}>Finalize committed outcome</Button>}</div>{verification&&<p className="verification" role="status">{verification}</p>}<h4>Evidence, finalization, and settlement transactions</h4>{activity.filter(log=>['EvidenceCommitted','OutcomeFinalized','PolicySettled'].includes(log.event)).map((log,i)=><div className="history-row" key={`${log.hash}-${i}`}><span>{log.event}</span><small>Block {log.block?.toString()}</small><HashLink hash={log.hash!} d={d}/></div>)}<h4>Capture audit trail</h4>{history.data?.attempts.map(attempt=><div className="history-row" key={attempt.id}><span>{attempt.status.toUpperCase()}</span><small>{date(attempt.completed_at)}</small><a href={`${d.evidenceOrigin}/evidence/${attempt.manifest_hash}`} target="_blank" rel="noreferrer">Inspect attempt <ExternalLink size={13}/></a></div>)}{!history.data?.attempts.length&&<p className="muted">No recorded capture attempts. Synthetic fixtures are precommitted separately.</p>}{history.error&&<p className="error">Evidence retrieval failed. Onchain hashes remain visible above.</p>}</section>;
}
function Operator({d,data,ready,address,walletClient,transact,installDeployment,setNotice}:{d:Deployment;data?:Protocol;ready:boolean;address?:Address;walletClient:WalletClient|undefined;transact:Tx;installDeployment:(d:Deployment)=>Promise<void>;setNotice:(s:string)=>void}){
  const [prepared,setPrepared]=useState<Prepared>();const [draftMode,setDraftMode]=useState('synthetic');const [draftOutcome,setDraftOutcome]=useState('YES');const [selected,setSelected]=useState('1');const [quoteManager,setQuoteManager]=useState(d.wallets.A);const [mode,setMode]=useState('1');const [captured,setCaptured]=useState<Record<string,unknown>>();const [captureRetryAt,setCaptureRetryAt]=useState<number|null>(null);const [captureState,setCaptureState]=useState('');
  const isAdmin=address?.toLowerCase()===d.wallets.A.toLowerCase(),isResolver=address?.toLowerCase()===data?.authority.toLowerCase();const event=data?.events.find(e=>e.id===BigInt(selected));
  const existingVault=data?.vaults.find(v=>v.quotingManager.toLowerCase()===quoteManager.toLowerCase()&&v.mode===Number(mode)&&v.phase<2&&v.issuanceDeadline>data.now);
  const coreVault=data?.vaults.find(v=>v.quotingManager.toLowerCase()===d.wallets.A.toLowerCase()&&v.mode===1&&v.phase<2&&v.issuanceDeadline>data.now);
  const preparedRegistered=!!prepared&&data?.events.some(e=>e.id.toString()===String(prepared.spec.eventId));
  const signedPost=(action:'capture'|'publish',body:Record<string,unknown>,payloadHash:Hex,eventId:string)=>signedEvidencePost(d,walletClient,address,action,body,payloadHash,eventId);

  async function publishPrepared(){try{if(!prepared)throw new Error('Load a prepared event bundle');const objects=[{kind:'specification',payload:prepared.spec},...(prepared.bundle?[{kind:'raw-fixture',payload:prepared.bundle.raw},{kind:'fixture-manifest',payload:prepared.bundle.manifest}]:[])];await signedPost('publish',{objects},hashJSON(objects),String(prepared.spec.eventId));setNotice('Specification and fixture archived independently. Hashes are immutable.');}catch(error){setNotice((error as Error).message);}}
  async function capture(){try{if(!event)throw new Error('Select event');setCaptured(undefined);setCaptureState('Requesting the exact committed ERA5 date…');setCaptureRetryAt(null);const result=await signedPost('capture',{},event.terms.specHash,event.id.toString());const bytes=await archivedBytes(`${d.evidenceOrigin}/evidence/${result.manifestHash}`,result.manifestHash);const manifest=JSON.parse(new TextDecoder().decode(bytes));if(manifest.validation)await verifiedResolverArgs(event,d,result.manifestHash);setCaptured(manifest);setCaptureRetryAt(result.retryAfter||null);setCaptureState(manifest.validation?'Archived rainfall, date, units, source, and hashes verified. Ready for authority review.':result.retryable?'ERA5 observation is unavailable or delayed. The failed attempt is archived; no rainfall will be committed.':`No eligible observation: ${manifest.error||'validation failed'}.`);setNotice(manifest.validation?'Frozen ERA5 snapshot verified. Review before committing onchain.':'ERA5 observation is pending or invalid. No resolution has been submitted.');}catch(error){setCaptured(undefined);setCaptureState((error as Error).message);setNotice((error as Error).message);}}
  async function commitVerified(){try{if(!event||!manifest||!data)throw new Error('Load an archived observation first.');if(address?.toLowerCase()!==data.authority.toLowerCase())throw new Error('Connect the authorized resolver wallet.');const args=await verifiedResolverArgs(event,d,hashJSON(manifest));await transact(d.contracts!.resolver,abis.DemoWeatherResolver,'commitEvidence',args);}catch(error){setNotice((error as Error).message);}}

  async function timeout(){try{if(!event)throw new Error('Select event');const response=await fetch(`${d.evidenceOrigin}/timeout`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({manager:d.contracts!.manager,eventId:event.id.toString()})});const result=await response.json();if(!response.ok)throw new Error(result.error);await transact(d.contracts!.resolver,abis.DemoWeatherResolver,'finalizeTimeoutInvalid',[event.requestId,result.evidenceURI]);}catch(error){setNotice((error as Error).message);}}
  const [weatherTemplate,setWeatherTemplate]=useState('pune:50000');
  function prepare(){try{if(!data)throw new Error('Wait for verified chain reads');setPrepared(prepareEvent(d,data.events.length+1,Number(data.now),draftMode,draftOutcome,{city:weatherTemplate.split(':')[0],thresholdMilliMm:weatherTemplate.split(':')[1]}) as unknown as Prepared);setNotice('Next event prepared from chain time. Register and archive it before preparing another.');}catch(error){setNotice((error as Error).message);}}
  async function loadFixture(){try{if(!event||event.terms.mode!==1)throw new Error('Select synthetic event');const response=await fetch(d.evidenceOrigin+'/evidence/'+event.terms.fixtureManifestHash);if(!response.ok)throw new Error('Fixture manifest unavailable');const bytes=new Uint8Array(await response.arrayBuffer());if(keccak256(bytes)!==event.terms.fixtureManifestHash)throw new Error('Fixture hash mismatch');const manifest=JSON.parse(new TextDecoder().decode(bytes));const specResponse=await fetch(event.terms.specificationURI),rawResponse=await fetch(d.evidenceOrigin+'/evidence/'+manifest.responseHash);if(!specResponse.ok||!rawResponse.ok)throw new Error('Archived fixture bundle unavailable');const spec=await specResponse.json();verifySpecificationTerms(spec,event.terms);verifyBundle(manifest,new Uint8Array(await rawResponse.arrayBuffer()),spec);setCaptured(manifest);setNotice('Precommitted replay evidence verified and loaded.');}catch(error){setNotice((error as Error).message);}}
  const manifest=event?.terms.mode===1?(captured||prepared?.bundle?.manifest):captured;
  return <><section className="panel"><h2>Basic demo · next step</h2>{!data?<p>Loading contract status…</p>:!coreVault?<p>Create a synthetic vault for Wallet A using the advanced setup below.</p>:coreVault.phase===0?<><p><strong>Fund vault #{coreVault.id.toString()}.</strong> It currently holds {money(coreVault.accountedAssets)} mUSDC.</p><p>Connect Wallet A. On <Link href="/buy/">Protection</Link>, click Claim mock USDC. Then on <Link href="/underwrite/">Underwrite</Link>, choose vault #{coreVault.id.toString()}: Approve deposit → Deposit 1,000 → Open underwriting.</p></>:!data.events.length?<p>Vault #{coreVault.id.toString()} is open. Below, click Prepare next event → Register event onchain → Publish spec + evidence. Use the default synthetic YES result.</p>:!data.policies.length?<p>The event is registered. Wallet A publishes a 200 / 25 quote on <Link href="/underwrite/">Underwrite</Link>. Wallet B claims mock USDC and buys on <Link href="/buy/">Protection</Link>. Archive the prepared evidence before purchase.</p>:<p>After purchase: connect Wallet A → Load archived fixture → Commit reviewed evidence → Finalize committed outcome. Then on <Link href="/policies/">Portfolio</Link>, click Settle policy.</p>}<p className="simulation-label">TESTNET DEMONSTRATION — SIMULATED EVENT RESULT</p></section><details className="panel"><summary>Advanced · deployment configuration and wallet addresses</summary><div className="card-top"><h2>Deployment configuration</h2><span className="pill">{d.contracts?'CONFIGURED ADDRESSES':'SIGNING REQUIRED'}</span></div><p className="muted">The public deployment is already configured. Import JSON only to inspect a different deployment; local Anvil is explicitly labeled as local.</p><label className="file-label">Import deployment JSON<input type="file" accept="application/json" onChange={async e=>{try{const file=e.target.files?.[0];if(file)await installDeployment(JSON.parse(await file.text()));}catch(error){setNotice((error as Error).message);}}}/></label><div className="fields-grid"><Field label="Wallet A · manager / resolver">{short(d.wallets.A)}</Field><Field label="Wallet B · buyer">{short(d.wallets.B)}</Field><Field label="Wallet C · competing manager">{short(d.wallets.C)}</Field><Field label="Evidence origin"><a href={d.evidenceOrigin} target="_blank" rel="noreferrer">Independent service <ExternalLink size={13}/></a></Field></div></details>
  <details className="panel"><summary>Advanced · create another vault</summary><h2>Create a vault only if needed</h2><p className="muted">Wallet A creates the vault. The chosen quoting manager funds it on Underwrite. Synthetic and live modes use separate vaults.</p><div className="vault-actions"><label>Quoting manager<select value={quoteManager} onChange={e=>setQuoteManager(e.target.value as Address)}><option value={d.wallets.A}>Wallet A</option><option value={d.wallets.C}>Wallet C · competitor</option></select></label><label>Event mode<select value={mode} onChange={e=>setMode(e.target.value)}><option value="1">Synthetic demonstration</option><option value="0">Live ERA5 event</option></select></label><Button disabled={!ready||!isAdmin||!!existingVault} onClick={()=>void transact(d.contracts!.manager,abis.AegisPolicyManager,'createVault',[quoteManager.toLowerCase(),data!.now+3n*86400n,[quoteManager.toLowerCase()],Number(mode)])}>Create vault epoch</Button></div>{existingVault&&<p className="muted">Vault #{existingVault.id.toString()} already exists for this manager and mode. Continue on <Link href="/underwrite/">Underwrite</Link>; creation is disabled to prevent duplicates.</p>}</details>
  {coreVault?.phase===1&&<section className="panel"><h2>2 · Prepare, register, then publish the event</h2><p className="muted">Prepare the next event from verified chain time, or import a generated JSON bundle. The document hash is checked before registration. Evidence is published to the independent service after the event exists.</p><div className="vault-actions"><details><summary>Advanced · event options</summary><label>Weather market<select aria-label="Weather market template" value={weatherTemplate} onChange={e=>setWeatherTemplate(e.target.value)}><option value="pune:50000">Pune � 50 mm</option><option value="mumbai:75000">Mumbai � 75 mm</option><option value="pune:20000">Pune � 20 mm</option></select></label><label>Dataset mode<select aria-label="Prepared event mode" value={draftMode} onChange={e=>setDraftMode(e.target.value)}><option value="synthetic">Synthetic demonstration</option><option value="live">Live ERA5</option></select></label><label>Fixed demo outcome<select aria-label="Prepared fixture outcome" value={draftOutcome} disabled={draftMode==='live'} onChange={e=>setDraftOutcome(e.target.value)}><option>YES</option><option>NO</option><option>INVALID</option></select></label></details><Button variant="outline" disabled={!data} onClick={prepare}>Prepare next event</Button>{prepared&&<a className="text-link" download={`aegis-event-${prepared.spec.eventId}.json`} href={'data:application/json;charset=utf-8,'+encodeURIComponent(JSON.stringify(prepared,null,2))}>Download prepared bundle <Download size={14}/></a>}</div><label className="file-label">Prepared event bundle<input type="file" accept="application/json" onChange={async e=>{try{const file=e.target.files?.[0];if(file){const parsed=JSON.parse(await file.text()) as Prepared;if(hashJSON(parsed.spec)!==parsed.terms.specHash)throw new Error('Specification hash mismatch');setPrepared(parsed);setNotice('Prepared specification hash verified.');}}catch(error){setNotice((error as Error).message);}}}/></label>{prepared&&<pre className="spec-preview">{JSON.stringify(prepared.spec,null,2)}</pre>}<div className="evidence-actions"><Button disabled={!ready||!isAdmin||!prepared||preparedRegistered} onClick={()=>void transact(d.contracts!.manager,abis.AegisPolicyManager,'registerEvent',[prepared!.terms])}>Register event onchain</Button><Button variant="outline" disabled={!ready||!isResolver||!prepared||!preparedRegistered} onClick={()=>void publishPrepared()}>Publish spec + evidence</Button></div></section>}
  {data?.policies.length? <section className="panel"><h2>3 · Record the result after a policy is purchased</h2><p className="muted">For a synthetic YES or NO event, load its archived fixture, commit it, then finalize. INVALID uses only its precommitted INVALID fixture. For live weather, capture is enabled only during the committed capture window.</p><label>Registered event<select value={selected} onChange={e=>{setSelected(e.target.value);setCaptured(undefined);setCaptureState('');setCaptureRetryAt(null);}}>{data?.events.map(e=><option key={e.id.toString()} value={e.id.toString()}>Event #{e.id.toString()} · {e.terms.mode===1?(e.weather?.mode==='historical-replay'?'HISTORICAL REPLAY':'SYNTHETIC'):'LIVE'} · {statusNames[e.resolution.status]}</option>)}</select></label>{event?.terms.mode===1&&<div className="simulation-label">TESTNET DEMONSTRATION — SIMULATED EVENT RESULT</div>}{captureState&&<div className="capture-state" role="status"><p>{captureState}</p>{captureRetryAt&&<small>Suggested retry: {date(captureRetryAt)}. Capture must finish before the market deadline.</small>}</div>}{manifest&&<pre className="spec-preview">{JSON.stringify(manifest,null,2)}</pre>}<div className="evidence-actions">{event?.terms.mode===1&&<Button variant="outline" onClick={()=>void loadFixture()}>Load archived fixture</Button>}<Button variant="outline" disabled={!ready||!isResolver||event?.terms.mode!==0||event.resolution.status!==1||data!.now<event.terms.captureEligibleAt||data!.now>=event.terms.resolutionDeadline} onClick={()=>void capture()}>Capture fixed ERA5 source</Button><Button disabled={!ready||!isResolver||!manifest?.validation||event?.resolution.status!==1||event?.terms.fixtureOutcome===3||String(manifest.eventId)!==event?.id.toString()} onClick={()=>void commitVerified()}>Commit reviewed evidence</Button><Button variant="outline" disabled={!ready||event?.resolution.status!==2} onClick={()=>void transact(d.contracts!.resolver,abis.DemoWeatherResolver,'finalize',[event!.requestId])}>Finalize committed outcome</Button><Button variant="outline" disabled={!ready||!isResolver||event?.terms.mode!==1||event.terms.fixtureOutcome!==3||event.resolution.status!==1} onClick={()=>void transact(d.contracts!.resolver,abis.DemoWeatherResolver,'finalizeSyntheticInvalid',[event!.requestId,`${d.evidenceOrigin}/evidence/${event!.terms.fixtureManifestHash}`])}>Finalize precommitted INVALID fixture</Button><Button variant="outline" disabled={!ready||event?.terms.mode!==0||event.resolution.status!==1||data!.now<event.terms.resolutionDeadline} onClick={()=>void timeout()}>Finalize 14-day timeout</Button></div><p className="tiny">Committed YES/NO evidence permanently disables timeout INVALID. Policy settlement follows finalization and is permissionless. No administrative policy cancellation exists.</p></section>:null}</>;
}



